import sys

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    out = []
    for s in data[1:1 + t]:
        digits = []
        for g in s.split(','):
            v = 0
            if g[0] == 'r':
                v += 4
            if g[1] == 'w':
                v += 2
            if g[2] == 'x':
                v += 1
            digits.append(str(v))
        out.append(''.join(digits))
    print('\n'.join(out))

main()

