def gen(rng):
    def rand_perm():
        return ','.join(''.join(ch if rng.random() < 0.5 else '-' for ch in 'rwx') for _ in range(3))
    def fmt(ps):
        return str(len(ps)) + '\n' + '\n'.join(ps)
    tests = [
        fmt(['rwx,r--,r--']),
        fmt(['---,---,---']),
        fmt(['rwx,rwx,rwx']),
        fmt(['r--,---,--x']),
        fmt(['-w-,-w-,-w-', 'rw-,r--,r--', '--x,--x,--x']),
    ]
    for k in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            tests.append(fmt([rand_perm() for _ in range(k)]))
    # every one of the 512 combinations
    groups = [''.join(ch if (m >> i) & 1 else '-' for i, ch in zip((2, 1, 0), 'rwx')) for m in range(8)]
    allp = [a + ',' + b + ',' + c for a in groups for b in groups for c in groups]
    rng.shuffle(allp)
    tests.append(fmt(allp))
    for _ in range(2):
        tests.append(fmt([rand_perm() for _ in range(100000)]))
    tests.append(fmt(['rwx,r--,r--'] * 100000))
    return tests

